public object Load {
    public object Agenda {
        public const val APP: String = "agenda"

        /** Non-cancelled events, soonest first, with the calendars they could land on, each event's calendar_id, link, reminders, its attachments and its guest list (each `{party_id, name, partstat, is_you}`, read from the event's attendee edges). Defaults to today forward; pass ISO `from`/`to` instants to read any visible range (month and week views do), including still-running multi-day events that began before `from`. A repeating event (rule set) is materialized into one row per occurrence inside the visible range, each carrying the series' real event_id, an `instance_key` for list render and the `original_start_local` an occurrence edit is keyed on; a skipped day is left out and a moved one is where it moved to. Every occurrence also carries where it falls in the request's `tz`. */
        public fun Upcoming(
            from: String? = null,
            to: String? = null,
        ): LoadRequest =
            load(APP, "upcoming") {
                from?.let { put("from", text(it)) }
                to?.let { put("to", text(it)) }
            }

        /** Full-text event search through the vault's one index (title, description and place) — returns only the ranked non-cancelled matches in the upcoming row shape plus a hit snippet, never a whole-table pull. */
        public fun Search(
            term: String,
        ): LoadRequest =
            load(APP, "search") {
                put("term", text(term))
            }

        /** The cross-app facts that decorate a calendar day, as one read-only projection: birthdays recurring inside the window (each `{party_id, name, month, day, tier}`, where `tier` is `inner` when the owner starred that person and `outer` otherwise), and holidays. Holidays are always `[]` today — the vault has no holiday source. It reads no task: a dated task is a row in its day, read from `tasks.board`. `from`/`to` are inclusive `YYYY-MM-DD` days, defaulting to today plus 45 days and capped at a 400-day span. */
        public fun DayContext(
            from: String? = null,
            to: String? = null,
        ): LoadRequest =
            load(APP, "day-context") {
                from?.let { put("from", text(it)) }
                to?.let { put("to", text(it)) }
            }

        /** Pickable people for the invite picker — each `{party_id, name, is_you}`, you sorted first. `me` is the owner's person id. No event data; just the directory the create-event attendee multi-select draws from. */
        public fun Parties(): LoadRequest =
            load(APP, "parties")
    }

    public object Docs {
        public const val APP: String = "docs"

        /** The drive as a bounded recent window: every folder, plus the most recently changed documents newest first — caller-sized via limit, default 200 — trashed ones included with their purge dates, each row decorated with starred, its free-form labels, and the current bytes' media_type and size. A document attached to something and filed in no folder is not listed. truncated=true means older documents exist beyond the window; the shelves Trash, Starred and Recent are read for themselves. */
        public fun Drive(
            limit: Int = 0,
        ): LoadRequest =
            load(APP, "drive", limit = limit)

        /** Full-text document search through the vault's one search index (title + the words extracted from the current bytes) — returns only the ranked matches in the drive's document row shape plus a hit snippet, never a whole-table pull. Trashed documents never match. */
        public fun Search(
            term: String,
        ): LoadRequest =
            load(APP, "search") {
                put("term", text(term))
            }

        /** A document's versions, newest first: the current bytes, then each revision a replace put down. A version's instant is when it became current — when the one before it was replaced, or the document was made for the oldest — so restoring an old version reads as the newest entry even though its bytes are old. A revision's seq is the version's number. */
        public fun History(
            documentId: String,
        ): LoadRequest =
            load(APP, "history") {
                put("document_id", text(documentId))
            }

        /** What was done to a document: the journal's executed commands that name it, newest first (the journal is the vault's evidence of every command). An empty list is honest: nothing has been done to it yet. */
        public fun Activity(
            documentId: String,
        ): LoadRequest =
            load(APP, "activity") {
                put("document_id", text(documentId))
            }
    }

