                put("range", text(range.wire))
                put("today", text(today))
            }

        /** A page of every workout, newest first, or one kind's, with each kind's count for the filter. */
        public fun Workouts(
            limit: Int = 0,
            cursor: String? = null,
            kindConceptId: String? = null,
        ): LoadRequest =
            load(APP, "workouts", limit = limit) {
                cursor?.let { put("cursor", text(it)) }
                kindConceptId?.let { put("kind_concept_id", text(it)) }
            }

        /** One workout: its kind, span and everything the store measured. */
        public fun Workout(
            activityId: String,
        ): LoadRequest =
            load(APP, "workout") {
                put("activity_id", text(activityId))
            }

        /** What the follower reads before a pass: the newest day and the newest workout the vault holds, and every daily total since a day, so it sends only what moved. */
        public fun FollowView(
            since: String,
        ): LoadRequest =
            load(APP, "follow-view") {
                put("since", text(since))
            }
    }

    public object Locker {
        public const val APP: String = "locker"

        /** A bounded window of non-trashed, non-archived items (caller-sized via limit, default 300, 2,000 at most), newest-updated first, each with its favorite star, free-form tags, a safe subtitle and the compromised flag. `total` is the live count from the vault itself, so the foot line can say "300 of 312" without reading the ceiling back to count it. Pass archived:true for the archive shelf. Secrets are NEVER in this payload — passwords, card numbers, CVVs, OTP seeds and note bodies stay out. */
        public fun Items(
            archived: Boolean? = null,
            limit: Int = 0,
        ): LoadRequest =
            load(APP, "items", limit = limit) {
                archived?.let { put("archived", flag(it)) }
            }

        /** One item's browsable fields for the detail pane, trashed or not: its connector alias, memo, owner-defined sections and fields, additional addresses and passkey metadata. Every sealed value — the type's own cells, a sealed custom field, a passkey's key — is reported only as PRESENT; its plaintext is the phone core's reveal, behind the unlock and a receipt. A type this build does not know reads as a note that still carries its fields. */
        public fun Item(
            itemId: String,
        ): LoadRequest =
            load(APP, "item") {
                put("item_id", text(itemId))
            }

        /** Match items by title, username or url, case-insensitively, over every item not in the trash, returning the same secret-free row shape as items. A note and a secret are never searched. */
        public fun Search(
            term: String,
        ): LoadRequest =
            load(APP, "search") {
                put("term", text(term))
            }

        /** Trashed items with their purge dates (secret-free row shape); on the phone the kit's one trash screen reads them. */
        public fun Trash(): LoadRequest =
            load(APP, "trash")

        /** Locker's access history: the receipts the vault already wrote — unlocks, reveals, copies and one-time codes, refusals included — newest first and windowed, and on the phone one item's at a time. Read from the vault's append-only receipts under a grant pinned to Locker's own objects. No receipt has ever carried a secret value, and this adds none. */
        public fun Access(
            itemId: String? = null,
            limit: Int = 0,
        ): LoadRequest =
            load(APP, "access", limit = limit) {
                itemId?.let { put("item_id", text(it)) }
            }
    }

    public object Money {
        public const val APP: String = "money"

        /** The Spending screen for a month: spent per currency against the plan, each category's planned, carried-in, spent and left, uncategorised rows, in/out/net, what was left out (transfers, rows dated after today) and the month-end forecast. Every figure is derived at read time and per currency. */
        public fun Spending(
            month: String,
        ): LoadRequest =
            load(APP, "spending") {
                put("month", text(month))
            }

        /** A page of a month's transactions, newest first, filtered by account and category, with the count that still need a category. */
        public fun Activity(
            month: String,
            accountId: String? = null,
            category: String? = null,
            cursor: String? = null,
            limit: Int = 0,
            uncategorised: Boolean? = null,
        ): LoadRequest =
            load(APP, "activity", limit = limit) {
                put("month", text(month))
                accountId?.let { put("account_id", text(it)) }
                category?.let { put("category", text(it)) }
                cursor?.let { put("cursor", text(it)) }
                uncategorised?.let { put("uncategorised", flag(it)) }
            }

        /** One transaction with its flags, a transfer it may be half of, the rule the app would propose, how often its merchant is seen and the recurring series it belongs to. */
        public fun Transaction(
            txnId: String,
        ): LoadRequest =
            load(APP, "transaction") {
                put("txn_id", text(txnId))
            }

        /** Twelve months of money in, out and net per currency, with the savings rate. The current month is marked partial. */
        public fun Cashflow(
            through: String,
        ): LoadRequest =
            load(APP, "cashflow") {
                put("through", text(through))
            }

        /** Accounts on and off budget with derived balances, the newest checkpoint against each, and net worth per currency. */
        public fun Accounts(): LoadRequest =
            load(APP, "accounts")

        /** The rules in the order they apply, with their specificity. */
        public fun Rules(): LoadRequest =
            load(APP, "rules")

        /** The categories: groups, then categories, archived ones marked. */
        public fun Categories(): LoadRequest =
            load(APP, "categories")

        /** The target sheet for a category in a month: the plan, what carried in, the six-month average and next month's preview. */
        public fun TargetSheet(
            categoryId: String,
            currency: String,
            month: String,
            amountMinor: Long? = null,
            carry: Boolean? = null,
        ): LoadRequest =
            load(APP, "target-sheet") {
                put("category_id", text(categoryId))
                put("currency", text(currency))
                put("month", text(month))
                amountMinor?.let { put("amount_minor", whole(it)) }
                carry?.let { put("carry", flag(it)) }
            }

        /** Recurring charges detected over thirteen months: cadence, amount, next due and status. Nothing is stored. */
        public fun Recurring(): LoadRequest =
            load(APP, "recurring")

        /** This month's spending per currency, for Home. */
        public fun HomeTile(
            month: String,
        ): LoadRequest =
            load(APP, "home-tile") {
                put("month", text(month))
            }

        /** Searches the newest twelve months of transactions by description, the member's name, category and memo, forgiving a slipped letter. */
        public fun Search(
            month: String,
            term: String,
            limit: Int = 0,
        ): LoadRequest =
            load(APP, "search", limit = limit) {
                put("month", text(month))
                put("term", text(term))
            }
    }

    public object Notes {
        public const val APP: String = "notes"

        /** FTS5 powerbox search across notes, people, events, tasks, documents and photos; returns secret-free entity-aware link targets. */
        public fun LinkTargets(
            term: String,
        ): LoadRequest =
            load(APP, "link-targets") {
                put("term", text(term))
            }

        /** A bounded recent window of notes (newest by updated_at, pinned always included) with their notebook names, a short body preview (`preview`) and checklist tally (`check`), and tags (`[{concept_id, label}]`), plus the notebooks for filtering and the distinct tag list (`[{concept_id, label}]`) seen within the window — never a whole-table pull, and never full bodies (the editor pulls those via `note`); `truncated` says older notes exist beyond the window. */
        public fun Library(
            limit: Int = 0,
        ): LoadRequest =
            load(APP, "library", limit = limit)

        /** One note's body — the editor's on-open pull. The library/search projections ship only a preview, so the full text is fetched lazily here when a note is opened. */
        public fun Note(
            noteId: String,
        ): LoadRequest =
            load(APP, "note") {
                put("note_id", text(noteId))
            }

        /** Full-text note search through the vault's FTS5 index (title + body) — returns only the ranked matches in the library row shape (preview + checklist tally, not full bodies) plus a hit snippet, never a whole-table pull. */
        public fun Search(
            term: String,
        ): LoadRequest =
            load(APP, "search") {
                put("term", text(term))
            }

        /** The selected note's body versions, newest first: the current words, then each version they replaced (newest 200; `truncated` says more exist). */
        public fun History(
            noteId: String,
        ): LoadRequest =
            load(APP, "history") {
                put("note_id", text(noteId))
            }

        /** The Journal place: a bounded, read-only window over the memos this vault holds (notes that are about a person or a thing) — the set the library, search and link-target projections exclude, read the other way round. Live entries only, newest by updated_at, with a short preview and checklist tally and never a full body; `truncated` says older entries exist beyond the window. */
        public fun Journal(
            limit: Int = 0,
        ): LoadRequest =
            load(APP, "journal", limit = limit)
    }

    public object People {
        public const val APP: String = "people"

        /** The people window as a bounded recent view, newest first, decorated with the star, the list, the reminders that are on and when they were last touched (computed from the touches); the owner and pets are not in it. */
        public fun People(
            limit: Int = 0,
        ): LoadRequest =
            load(APP, "people", limit = limit)

        /** One person's sheet: the roster row, nickname, how you met, contact points with who else holds the same value, dates, notes and the touch log. */
        public fun Person(
            partyId: String,
        ): LoadRequest =
            load(APP, "person") {
                put("party_id", text(partyId))
            }

        /** The keep-in-touch summary: who is overdue to reconnect with (people with no cadence never are), upcoming reminders (nearest first), recent logged touches, and the headline counts (all / reconnect / upcoming / favorites, plus linked / to_link — null when the sharing reads are denied). */
        public fun Dashboard(): LoadRequest =
            load(APP, "dashboard")

        /** Full-text people search over the one vault index — name, nickname, role, how you met, contact points and the notes about them — ranked, with a snippet. */
        public fun Search(
            term: String,
        ): LoadRequest =
            load(APP, "search") {
                put("term", text(term))
            }

        /** People profiles in reversible trash, with purge dates and safe display metadata. */
        public fun Trash(): LoadRequest =
            load(APP, "trash")
    }

    public object Photos {
        public const val APP: String = "photos"

        /** A bounded recent window of live photographs (newest by taken_at, not archived, an edit folding the original it was made from) with their bytes' media type and size plus the albums they belong to — never a whole-table pull; trashed photographs ride separately (newest 200) with their days-until-purge, and `truncated` says older photographs exist beyond the window. Each photograph also carries `place` and `tags`; `places` is the full known place list. `before` is a keyset cursor (only photographs taken strictly earlier), and `tail` reports the oldest timestamp this page reached — pass it back as the next `before`. */
        public fun Library(
            before: String? = null,
            limit: Int = 0,
        ): LoadRequest =
            load(APP, "library", limit = limit) {
                before?.let { put("before", text(it)) }
            }

        /** Caption and place search over the whole live library through the vault's one search index (the caption, the place's name and its locality) — not just the loaded window; returns the ranked photograph ids a grid reads, leaving out the archive. */
        public fun Search(
            term: String? = null,
        ): LoadRequest =
            load(APP, "search") {
                term?.let { put("term", text(it)) }
            }

        /** Near-duplicate clusters over the live library: groups the photographs whose perceptual hashes (a derivative of each blob) lie within a few bits of one another, recomputed at read — a true visual-similarity signal, not a coincidence-prone fingerprint, and nothing stored. */
        public fun Duplicates(): LoadRequest =
            load(APP, "duplicates")
    }

    public object Tasks {
        public const val APP: String = "tasks"

        public enum class BoardView(internal val wire: String) { Today("today"), Upcoming("upcoming"), Inbox("inbox"), Anytime("anytime"), All("all"), Logbook("logbook"), Reminders("reminders"), Project("project") }

        /** The task board as a bounded window (newest open tasks by creation, caller-sized, families kept whole; the logbook read is capped at its visible 50 most recently closed), each row carrying its tags (`[{concept_id, label}]`) and what it is about, plus the distinct tag list (`[{concept_id, label}]`) seen within the window — never a whole-table pull; `truncated` is the open walk's own cursor — it exists or it does not — rather than a guess from the row count. */
        public fun Board(
            limit: Int = 0,
            projectId: String? = null,
            view: BoardView? = null,
        ): LoadRequest =
            load(APP, "board", limit = limit) {
                projectId?.let { put("project_id", text(it)) }
                view?.let { put("view", text(it.wire)) }
            }

        /** Full-text task search through the vault's one index (title, description and project) — returns only the ranked matches in the board's per-task row shape plus a hit snippet, never a whole-table pull. */
        public fun Search(
            term: String,
        ): LoadRequest =
            load(APP, "search") {
                put("term", text(term))
            }

        /** One task by id, whether or not any board window holds it: the task with its subtasks, tags, project and section, and its parent when it is a subtask. */
        public fun Task(
            taskId: String,
        ): LoadRequest =
            load(APP, "task") {
                put("task_id", text(taskId))
            }

        /** The live projects and their sections, with open counts, in their order. */
        public fun Projects(): LoadRequest =
            load(APP, "projects")

        /** What fell behind while the member was away: dated work past due, repeating work that missed occurrences, and undated work sitting too long, each as a pile. */
        public fun CatchUp(): LoadRequest =
            load(APP, "catch-up")

        /** The tasks in the 30-day trash, most recently trashed first, each with when it was deleted and when it is erased. */
        public fun Trash(): LoadRequest =
            load(APP, "trash")
    }

